<template>
  <div class="page"><header class="page-header"><div><div class="eyebrow">People</div><h1 class="page-title">Your team</h1><p class="page-subtitle">See who’s working with you and how the team is structured.</p></div></header><section class="team-stats"><div class="card team-stat"><span class="stat-label">TOTAL MEMBERS</span><strong>{{members.length}}</strong></div><div class="card team-stat"><span class="stat-label">MANAGERS</span><strong>{{members.filter(m=>m.role==='MANAGER').length}}</strong></div><div class="card team-stat"><span class="stat-label">EMPLOYEES</span><strong>{{members.filter(m=>m.role==='EMPLOYEE').length}}</strong></div></section><div class="toolbar"><div class="search-box"><input v-model="search" placeholder="Search by name or email…"/></div></div><div class="card table-card"><table class="table"><thead><tr><th>Member</th><th>Role</th><th>Email</th><th>Status</th></tr></thead><tbody><tr v-for="m in filtered" :key="m.id"><td><div class="member"><span class="member-avatar">{{m.name?.charAt(0)}}</span><div><strong>{{m.name}}</strong><span>Team member</span></div></div></td><td><span class="role-badge" :class="m.role.toLowerCase()">{{m.role}}</span></td><td class="date">{{m.email}}</td><td><span class="active">● Active</span></td></tr></tbody></table><div v-if="!filtered.length" class="empty"><strong>No members found</strong><span>Try another search.</span></div></div></div>
</template>
<script setup>
import {ref,computed,onMounted} from 'vue';import api from '../services/api';const members=ref([]),search=ref('');const filtered=computed(()=>members.value.filter(m=>`${m.name} ${m.email}`.toLowerCase().includes(search.value.toLowerCase())));onMounted(async()=>{try{members.value=(await api.get('/users')).data||[]}catch(e){console.error(e)}})
</script>
